import 'package:audioplayers/audioplayers.dart';
import 'package:flutter/foundation.dart';
import 'package:flutter/services.dart';

enum Sfx { move, capture, check, end, notify, lowTime }

/// Sound + haptic feedback. Sounds are short original WAVs generated by
/// `tool/make_sfx.py`; haptics only fire on platforms with a vibration motor.
class Feedback {
  Feedback({this.enabled = true, this.haptics = true});

  bool enabled;
  bool haptics;
  bool _failed = false;

  final _players = <AudioPlayer>[];
  int _next = 0;

  Future<void> warmUp() async {
    if (_players.isNotEmpty) return;
    for (var i = 0; i < 3; i++) {
      final player = AudioPlayer(playerId: 'gc-sfx-$i');
      await player.setReleaseMode(ReleaseMode.stop);
      await player.setPlayerMode(PlayerMode.lowLatency);
      _players.add(player);
    }
  }

  Future<void> play(Sfx sfx) async {
    _haptic(sfx);
    if (!enabled || _failed) return;
    try {
      await warmUp();
      final player = _players[_next++ % _players.length];
      await player.stop();
      await player.play(AssetSource('sfx/${_file(sfx)}'), volume: 0.9);
    } catch (e) {
      // Autoplay policies (web) or missing audio devices (CI) must never
      // break gameplay: disable sound after the first failure.
      _failed = true;
      debugPrint('sfx disabled: $e');
    }
  }

  void _haptic(Sfx sfx) {
    if (!haptics || kIsWeb) return;
    final mobile =
        defaultTargetPlatform == TargetPlatform.iOS ||
        defaultTargetPlatform == TargetPlatform.android;
    if (!mobile) return;
    switch (sfx) {
      case Sfx.move:
        HapticFeedback.selectionClick();
      case Sfx.capture:
        HapticFeedback.lightImpact();
      case Sfx.check:
      case Sfx.notify:
        HapticFeedback.mediumImpact();
      case Sfx.end:
        HapticFeedback.heavyImpact();
      case Sfx.lowTime:
        break;
    }
  }

  String _file(Sfx sfx) => switch (sfx) {
    Sfx.move => 'move.wav',
    Sfx.capture => 'capture.wav',
    Sfx.check => 'check.wav',
    Sfx.end => 'end.wav',
    Sfx.notify => 'notify.wav',
    Sfx.lowTime => 'lowtime.wav',
  };

  Future<void> dispose() async {
    for (final p in _players) {
      await p.dispose();
    }
  }
}
